// Podcast automatique : une fois par jour, au premier passage après 7h05.
// Lancement manuel ou via /podcast : toujours.
const memoire = $getWorkflowStaticData('global');
const aujourdhui = $now.setZone('Europe/Paris').toISODate();
// Lancement automatique = le bloc de planification a été déclenché.
// (Attention : $execution.mode vaut « production » et non « trigger » dans un bloc Code.)
const automatique = $('Toutes les heures (7h05-21h05)').isExecuted;
if (automatique && memoire.dernierEnvoi === aujourdhui) return [];
// silencieux : le rapport renvoie ses données au lieu d'envoyer un message
return [{ json: { aujourdhui, silencieux: true } }];

// Rassemble les informations du jour en un texte pour le cerveau.
// Ta journée n'est décrite que de façon GÉNÉRALE (aucun titre, aucun sujet de mail).
const lire = nom => { try { return $(nom).all().map(i => i.json); } catch { return []; } };
const maintenant = $now.setZone('Europe/Paris');
const ilYa = jours => maintenant.minus({ days: jours }).toMillis();

const journee = lire('Ma journée (rapport)')[0] ?? {};
const kevBrut = lire('Lire CISA KEV')[0] ?? {};
const kev = (kevBrut.vulnerabilities ?? [])
  .filter(v => new Date(v.dateAdded).getTime() >= ilYa(2))
  .map(v => `- ${v.vendorProject} ${v.product} : ${v.vulnerabilityName}. ${v.shortDescription}` +
            (v.knownRansomwareCampaignUse === 'Known' ? ' (utilisée par des ransomwares)' : ''));
const certfr = lire('Lire CERT-FR')
  .filter(a => a.isoDate && new Date(a.isoDate).getTime() >= ilYa(3))
  .map(a => `- ${a.title}`);
const nvdBrut = lire('Lire NVD (critiques)')[0] ?? {};
const nvd = (nvdBrut.vulnerabilities ?? []).map(({ cve }) => ({
  score: cve.metrics?.cvssMetricV31?.[0]?.cvssData?.baseScore ?? cve.metrics?.cvssMetricV40?.[0]?.cvssData?.baseScore ?? 0,
  desc: cve.descriptions?.find(d => d.lang === 'en')?.value ?? '',
})).sort((a, b) => b.score - a.score);

const blocs = [
  `Date : ${maintenant.setLocale('fr').toFormat('cccc d LLLL yyyy')}`,
  '',
  'TA JOURNÉE (informations générales uniquement) :',
  journee.aujourdhui ? JSON.stringify(journee) : 'Indisponible ce matin : ne pas en parler.',
  '',
  'ACTU CYBER :',
  `Vulnérabilités ajoutées au catalogue CISA KEV (exploitées activement) ces 2 derniers jours : ${kev.length}`,
  ...kev.slice(0, 6),
  `Alertes CERT-FR ces 3 derniers jours : ${certfr.length}`,
  ...certfr.slice(0, 4),
  `Nouvelles CVE critiques (NVD) ces dernières 24 h : ${nvd.length}. Les plus graves :`,
  ...nvd.slice(0, 3).map(v => `- CVSS ${v.score} : ${v.desc.slice(0, 300)}`),
];
return [{ json: { question: blocs.join('\n') } }];

// Extrait le JSON du script (tolère un éventuel bloc ``` autour)
const r = $input.first().json;
if (r.error || !r.reponse) throw new Error(`Le cerveau n'a pas répondu : ${String(r.error?.message ?? r.erreur ?? 'réponse vide').slice(0, 200)}`);
const brut = r.reponse.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
let script;
try { script = JSON.parse(brut.slice(brut.indexOf('{'), brut.lastIndexOf('}') + 1)); }
catch { throw new Error('Le script du podcast n\'est pas un JSON valide'); }
const repliques = (script.repliques ?? []).filter(x => x?.texte);
if (repliques.length < 2) throw new Error('Le script du podcast est vide');
return [{ json: { repliques } }];

// Mémorise que le podcast automatique du jour est parti (seulement APRÈS l'envoi réussi)
if (!$('Toutes les heures (7h05-21h05)').isExecuted) return [];
$getWorkflowStaticData('global').dernierEnvoi = $('Déjà envoyé aujourd\'hui ?').first().json.aujourdhui;
return [];
